<?php
/**
 * Static 600x600 SSB map for embedding in a QRZ.com profile (no JavaScript).
 *
 * Points and great-circle paths are drawn as HTML/SVG over the background
 * generated by scripts/make_background.php. The projection matches that image:
 * longitude centred on the QTH, latitude in Web Mercator (clamped to +/-85.05).
 * The station comes from the query string (map-ssb-qrz.php?LU2MET), or is
 * default_station.
 */

require __DIR__ . '/scripts/common.php';
$call = usePublicStation();

header('Cache-Control: private, no-store, no-cache, must-revalidate, max-age=0');
header('Pragma: no-cache');
header('Expires: 0');

const MAP_SIZE = 600;
const BAND_COLORS = ['10M' => '#e45756', '15M' => '#f28e2b', '20M' => '#59a14f', '40M' => '#4e79a7', '80M' => '#7b61a8'];
const DEFAULT_COLOR = '#68747d';

$cache = readJson(stationData('qso_cache.json')) ?? [];
$station = $cache['station'] ?? (loadConfig(false)['map'] ?? []);
$qthCall = (string)($station['callsign'] ?? $station['my_callsign'] ?? '');
$qthGrid = strtoupper((string)($station['grid'] ?? $station['my_grid'] ?? ''));
$qth = gridCentre($qthGrid) ?? [0.0, 0.0];

function shortestLongitude(float $longitude, float $origin): float {
    return $origin + fmod($longitude - $origin + 540, 360) - 180;
}

function greatCirclePoints(array $start, array $end, int $count = 48): array {
    $toRadians = M_PI / 180;
    $a = [cos($start[0] * $toRadians) * cos($start[1] * $toRadians), cos($start[0] * $toRadians) * sin($start[1] * $toRadians), sin($start[0] * $toRadians)];
    $b = [cos($end[0] * $toRadians) * cos($end[1] * $toRadians), cos($end[0] * $toRadians) * sin($end[1] * $toRadians), sin($end[0] * $toRadians)];
    $angle = acos(max(-1, min(1, $a[0] * $b[0] + $a[1] * $b[1] + $a[2] * $b[2])));
    if ($angle < 0.000001) return [$start, $end];
    $sinAngle = sin($angle);
    $points = [];
    $previousLon = $start[1];
    for ($index = 0; $index <= $count; $index++) {
        $fraction = $index / $count;
        $w1 = sin((1 - $fraction) * $angle) / $sinAngle;
        $w2 = sin($fraction * $angle) / $sinAngle;
        $x = $w1 * $a[0] + $w2 * $b[0];
        $y = $w1 * $a[1] + $w2 * $b[1];
        $z = $w1 * $a[2] + $w2 * $b[2];
        $previousLon = shortestLongitude(atan2($y, $x) / $toRadians, $previousLon);
        $points[] = [atan2($z, sqrt($x * $x + $y * $y)) / $toRadians, $previousLon];
    }
    return $points;
}

function mapX(float $longitude, float $qthLongitude): float {
    return (normalizeLongitude($longitude - $qthLongitude) + 180.0) / 360.0 * MAP_SIZE;
}

function mapY(float $latitude): float {
    $limit = 85.0511287798;
    $lat = deg2rad(max(-$limit, min($limit, $latitude)));
    return (0.5 - log(tan(M_PI / 4 + $lat / 2)) / (2 * M_PI)) * MAP_SIZE;
}

function esc(string $value): string {
    return htmlspecialchars($value, ENT_QUOTES, 'UTF-8');
}

// One point per callsign + grid + band, phone/CW QSOs only.
$groups = [];
foreach ($cache['qsos'] ?? [] as $qso) {
    if (!in_array(strtoupper((string)($qso['mode'] ?? '')), PHONE_MODES, true)) continue;
    $position = gridCentre((string)($qso['grid'] ?? ''));
    if ($position === null) continue;
    $band = strtoupper((string)($qso['band'] ?? ''));
    $key = ($qso['call'] ?? '') . '|' . strtoupper($qso['grid']) . '|' . $band;
    $groups[$key] ??= [
        'label' => trim(($qso['call'] ?? '') . ' ' . $qso['grid'] . ' ' . $band),
        'position' => [$position[0], shortestLongitude($position[1], $qth[1])],
        'color' => BAND_COLORS[$band] ?? DEFAULT_COLOR,
    ];
}

// Unique URL per response so QRZ never reuses a stale background.
$backgroundUrl = 'background.php?' . $call . '&v=' . rawurlencode((string)microtime(true));
?>
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=600">
<title><?= esc($qthCall) ?> SSB map</title>
<style>
html, body { margin: 0; padding: 0; background: #d9e2e5; }
.qrz-map { position: relative; display: block; width: 600px; height: 600px; overflow: hidden; font: 14px Arial, sans-serif; text-decoration: none; background: url('<?= esc($backgroundUrl) ?>') center / 600px 600px no-repeat; }
.qrz-map-lines { position: absolute; inset: 0; width: 600px; height: 600px; }
.qrz-map-point { position: absolute; width: 4px; height: 4px; margin: -2px 0 0 -2px; border: 1px solid #fff; border-radius: 50%; box-shadow: 0 1px 2px rgba(0,0,0,.4); }
.qrz-map-qth { background: #f3c969; border-color: #18343a; width: 6px; height: 6px; margin: -3px 0 0 -3px; }
.qrz-map-label { position: absolute; left: 10px; top: 10px; padding: 7px 10px; color: #18343a; background: rgba(255,255,255,.92); border-radius: 4px; font-weight: bold; }
.qrz-map-count { font-weight: normal; }
</style>
</head>
<body>
<a href="map-ssb.html?<?= esc($call) ?>" target="_blank" rel="noopener noreferrer" class="qrz-map" aria-label="Open the interactive map">
    <svg class="qrz-map-lines" viewBox="0 0 600 600" aria-hidden="true">
<?php foreach ($groups as $group):
    $path = array_map(fn($point) => round(mapX($point[1], $qth[1]), 1) . ',' . round(mapY($point[0]), 1), greatCirclePoints($qth, $group['position']));
?>
        <polyline points="<?= implode(' ', $path) ?>" fill="none" stroke="<?= $group['color'] ?>" stroke-width="0.8" stroke-opacity=".8" />
<?php endforeach; ?>
    </svg>
    <div class="qrz-map-point qrz-map-qth" style="left:<?= round(mapX($qth[1], $qth[1]), 1) ?>px;top:<?= round(mapY($qth[0]), 1) ?>px" title="<?= esc($qthCall . ' ' . $qthGrid) ?>"></div>
<?php foreach ($groups as $group): ?>
    <div class="qrz-map-point" style="left:<?= round(mapX($group['position'][1], $qth[1]), 1) ?>px;top:<?= round(mapY($group['position'][0]), 1) ?>px;background:<?= $group['color'] ?>" title="<?= esc($group['label']) ?>"></div>
<?php endforeach; ?>
    <div class="qrz-map-label"><?= esc($qthCall) ?> SSB <span class="qrz-map-count"><?= count($groups) ?> locations</span></div>
</a>
</body>
</html>
